+    function digits(n){return String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])}
+    function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
+    function renderSuspects(){ $('#suspectList').innerHTML=suspects.map(s=>`<button class="suspect ${state.person===s.id?'selected':''}" data-person="${s.id}"><span class="portrait">${s.mark}</span><span class="suspect-text"><b>${s.name}</b><small>${s.role}</small><span class="status ${state.talked.has(s.id)?'talked':''}">${state.talked.has(s.id)?'تم الاستجواب':'بانتظار الاستجواب'}</span></span><span class="arrow">‹</span></button>`).join('');$$('[data-person]').forEach(b=>b.onclick=()=>selectPerson(b.dataset.person));$('#accuseBtn').disabled=state.found.size<3||state.finished}
+    function renderEvidence(){const list=$('#evidenceList');list.innerHTML=state.found.size? [...state.found].map(id=>{const c=clues[id];return `<div class="evidence-item"><span class="e-icon">${c.icon}</span><div><b>${c.name}</b><small>${c.text}</small></div></div>`}).join(''):'<div class="evidence-empty">لم تُجمع أدلة بعد.<br>ابدأ بتفحّص أرجاء القصر.</div>';$('#evidenceCount').textContent=`${digits(state.found.size)} / ٦`;$('#progressLabel').textContent=`الأدلة ${digits(state.found.size)} / ٦`;$('#progressBar').style.width=`${state.found.size/6*100}%`;$('#accuseBtn').disabled=state.found.size<3||state.finished;}
+    function renderPlace(){const p=places[state.location];$('#locationTitle').textContent=p.title;$('#locationSub').textContent=p.sub;$('#sceneCaption').textContent=p.caption;$$('.loc-btn').forEach(b=>b.classList.toggle('active',b.dataset.location===state.location));const art=$('#sceneArt');art.querySelectorAll('.hotspot').forEach(x=>x.remove());p.hotspots.forEach(([id,label],i)=>{const b=document.createElement('button');b.className=`hotspot ${['one','two','three','four'][i]}`;b.dataset.clue=id;b.textContent=state.found.has(id)?'✓ '+clues[id].name:label;art.appendChild(b);b.onclick=()=>collect(id)});const decor=state.location==='office';art.querySelector('.body-silhouette').style.display=decor?'':'none';art.querySelector('.blood').style.display=decor?'':'none';art.querySelector('.desk').style.display=decor?'':'none';art.querySelector('.window').style.display=state.location==='office'||state.location==='garden'?'':'none';}
+    function collect(id){if(state.finished)return;if(state.found.has(id)){toast('هذا الدليل موجود بالفعل في دفتر الأدلة.');return}const c=clues[id];state.found.add(id);renderEvidence();renderSuspects();toast(`أُضيف إلى دفتر الأدلة: ${c.name}`);if(state.person){const s=suspects.find(x=>x.id===state.person);if(s.id==='samer'&&(id==='camera'||id==='print'||id==='letter'))showBubble(`واجهته بالدليل: <strong>${c.name}</strong>. ارتبك سامر، ثم قال: «لا بد أن أحداً يريد تلفيقي!»`)} }
+    function selectPerson(id){if(state.finished)return;state.person=id;const s=suspects.find(x=>x.id===id);state.talked.add(id);renderSuspects();$('#chatHint').textContent=`استجواب ${s.name} — اختر موضوعاً أو اكتب سؤالك`;$('#chatPerson').innerHTML=`<div class="portrait">${s.mark}</div><div><b>${s.name}</b><small>${s.role}</small></div>`;$('#questionInput').disabled=false;$('#askBtn').disabled=false;$('#chatFlow').innerHTML=`<div class="bubble"><strong>${s.name}:</strong> تفضّل يا حضرة المحقق. ماذا تريد أن تعرف؟</div><div class="topic-row"><button class="topic" data-topic="time">أين كنت وقت الجريمة؟</button><button class="topic" data-topic="victim">علاقتك بنديم؟</button><button class="topic" data-topic="evidence">ما رأيك بالأدلة؟</button></div>`;$$('[data-topic]').forEach(b=>b.onclick=()=>ask(b.dataset.topic));$('#questionInput').focus()}
+    function showBubble(text){const f=$('#chatFlow');f.innerHTML=`<div class="bubble">${text}</div><div class="topic-row"><button class="topic" data-topic="time">أين كنت وقت الجريمة؟</button><button class="topic" data-topic="victim">علاقتك بنديم؟</button><button class="topic" data-topic="evidence">ما رأيك بالأدلة؟</button></div>`;$$('[data-topic]').forEach(b=>b.onclick=()=>ask(b.dataset.topic))}
+    function ask(topic){if(!state.person)return;const s=suspects.find(x=>x.id===state.person);let key=topic;if(!['time','victim','evidence'].includes(topic)){const q=topic.toLowerCase();key=/وقت|أين|كنت|ساعة|جريمة|ليلة/.test(q)?'time':/نديم|ضحية|علاقة|دافع|مال|وصية/.test(q)?'victim':'evidence';}
+      let reply=s.topics[key];if(s.id==='samer'&&key==='evidence'&&(state.found.has('camera')||state.found.has('print')||state.found.has('letter'))){reply=state.found.has('camera')?'قلت إن العاصفة عطّلتها؟ لا أتذكر… ربما انقطع السلك قبل ذلك. ليس لدي ما أضيفه.':state.found.has('print')?'هذا ليس حذائي! لم أغادر البوابة، أقسم لك.':state.found.has('letter')?'السيد نديم كان يبالغ. لم أسرق شيئاً، مهما كتب في تلك الرسالة.'}
+      if(s.id==='rami'&&key==='evidence'&&state.found.has('vial'))reply='لا أعرف كيف وصلت القارورة إلى هناك. شخص ما أراد أن يبدو المطبخ مصدر السم.';
+      if(s.id==='layla'&&key==='time'&&state.found.has('print'))reply='إذا كان أثر الحذاء للحارس، فهذا يعني أنه كذب بشأن البوابة. أخبرتك أنني رأيته قرب المكتب.';
+      showBubble(`<strong>${s.name}:</strong> ${reply}`);state.asked[s.id]=(state.asked[s.id]||0)+1;}
