+    function closeModal(){$('#modalBackdrop').classList.remove('open')}
+    function accuse(){if(state.found.size<3)return;state.accuse=null;openModal(`<div class="eyebrow">حان وقت كشف الحقيقة</div><h2>من قتل نديم؟</h2><p>اختر المشتبه به الذي تظن أنه ارتكب الجريمة. فكّر في الدافع، والفرصة، وما تقوله الأدلة.</p><div class="modal-suspects">${suspects.map(s=>`<button class="choice" data-choice="${s.id}">${s.name} — ${s.role}</button>`).join('')}</div><div class="modal-actions"><button id="cancelModal">العودة للتحقيق</button><button class="primary" id="submitAccuse" disabled>تأكيد الاتهام</button></div>`);$$('[data-choice]').forEach(b=>b.onclick=()=>{state.accuse=b.dataset.choice;$$('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));$('#submitAccuse').disabled=false});$('#cancelModal').onclick=closeModal;$('#submitAccuse').onclick=showResult;}
