45:   <script>
46:     const clues={
47:       tea:{name:'سمّ في فنجان الشاي',icon:'☕',where:'مكتب الضحية',text:'آثار نبات الدفلى السام على حافة الفنجان. الشخص الذي أعدّ الشاي يعرف أن نديم كان يشربه كل ليلة.'},
48:       clock:{name:'الساعة المتوقفة',icon:'◷',where:'مكتب الضحية',text:'توقفت الساعة عند ١٠:١٧، لكن زجاجها سليم. يبدو أنها أُوقفت يدوياً لتضليل وقت الوفاة.'},
49:       letter:{name:'رسالة ممزّقة',icon:'✉',where:'مكتب الضحية',text:'جزء من رسالة يهدد فيها نديم بطرد الحارس سامر بعد اكتشاف اختفاء مقتنيات من القصر.'},
50:       vial:{name:'قارورة الدفلى',icon:'⚗',where:'المطبخ',text:'قارورة صغيرة مخبأة خلف أكياس الدقيق. عليها بصمات ممسوحة ورائحة الدفلى نفسها الموجودة في الشاي.'},
51:       camera:{name:'كاميرا معطّلة',icon:'◉',where:'المدخل',text:'سلك الكاميرا قُطع من داخل غرفة الحراسة قبل دقائق من الوفاة. لا يملك مفتاح الغرفة سوى الحارس سامر.'},
52:       print:{name:'أثر طين عند النافذة',icon:'⌁',where:'الحديقة',text:'أثر حذاء عسكري مبلل تحت نافذة المكتب. مقاسه مطابق لحذاء الحارس، رغم ادعائه أنه لم يغادر البوابة.'}
53:     };
54:     const suspects=[
55:       {id:'layla',name:'ليلى',role:'ابنة أخ الضحية',mark:'ل',topics:{time:'كنت في الشرفة طوال الوقت… أو هكذا ظننت. رأيت سامر يخرج من جهة المكتب بعد العاشرة بقليل.',victim:'كان عمي قاسياً، لكنه كان سيغيّر وصيته لي. لم أقتله من أجل المال.',evidence:'وجدت رسالة على مكتبه تتحدث عن طرد سامر. لم أرد أن أتدخل في شؤونه.'},keywords:['شرفة','سامر','وصية']},
56:       {id:'rami',name:'رامي',role:'طاهي القصر',mark:'ر',topics:{time:'أعددت الشاي عند التاسعة وخمسين دقيقة. تركته على الصينية قرب المكتب وعدت للمطبخ.',victim:'خدمت السيد نديم خمسة عشر عاماً. كان صعب المراس، لكنه وثق بي.',evidence:'أنا أستخدم الأعشاب في الطبخ، لكن الدفلى سامة. لم ألمسها قط. المطبخ كان مفتوحاً للجميع.'},keywords:['شاي','مطبخ','دفلى']},
57:       {id:'hala',name:'هالة',role:'طبيبة العائلة',mark:'هـ',topics:{time:'غادرت القصر قرابة العاشرة. كنت مع ليلى في الصالون قبلها، ويمكنها تأكيد ذلك.',victim:'كان نديم يعاني من الأرق. أوصيته بتقليل الشاي، لا بتناول أي دواء.',evidence:'الوفاة لم تكن طبيعية. وجدت رائحة مرّة في الفنجان، شبيهة بسم نباتي.'},keywords:['فنجان','دواء','وفاة']},
58:       {id:'samer',name:'سامر',role:'حارس القصر',mark:'س',topics:{time:'لم أغادر البوابة طوال الليل. الساعة العاشرة وسبع عشرة دقيقة؟ كنت أراقب المدخل.',victim:'كان السيد نديم رجلاً محترماً. لا أعرف شيئاً عن رسائله أو ممتلكاته.',evidence:'الكاميرا تعطلت بسبب العاصفة، لا بسبب أحد. ولم أدخل المكتب هذه الليلة.'},keywords:['كاميرا','بوابة','مكتب']}
59:     ];
60:     const places={office:{title:'مكتب الضحية',sub:'آخر مكان شوهد فيه نديم حيّاً',caption:'انقر على العلامات الذهبية لفحص الأشياء',hotspots:[['tea','✦ فنجان الشاي'],['clock','✦ الساعة'],['letter','✦ الرسالة']]},kitchen:{title:'مطبخ القصر',sub:'مكان إعداد الشاي الأخير',caption:'تفقّد الرفوف خلف أكياس الدقيق',hotspots:[['vial','✦ الرف الخلفي']]},hall:{title:'المدخل وغرفة الحراسة',sub:'نقطة مراقبة القصر',caption:'افحص صندوق الكاميرات عند المدخل',hotspots:[['camera','✦ كاميرا المراقبة']]},garden:{title:'حديقة القصر',sub:'الأرض مبتلّة بعد عاصفة الليل',caption:'آثار أقدام قرب نافذة المكتب',hotspots:[['print','✦ أثر الحذاء']]} };
61:     const state={found:new Set(),talked:new Set(),location:'office',person:null,asked:{},finished:false,accuse:null};
62:     const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
63:     function digits(n){return String(n).replace(/[0-9]/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])}
64:     function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
65:     function renderSuspects(){ $('#suspectList').innerHTML=suspects.map(s=>`<button class="suspect ${state.person===s.id?'selected':''}" data-person="${s.id}"><span class="portrait">${s.mark}</span><span class="suspect-text"><b>${s.name}</b><small>${s.role}</small><span class="status ${state.talked.has(s.id)?'talked':''}">${state.talked.has(s.id)?'تم الاستجواب':'بانتظار الاستجواب'}</span></span><span class="arrow">‹</span></button>`).join('');$$('[data-person]').forEach(b=>b.onclick=()=>selectPerson(b.dataset.person));$('#accuseBtn').disabled=state.found.size<3||state.finished}
