const errors=[];const logs=[];
page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')logs.push(m.text())});
await page.goto('http://localhost:3002',{waitUntil:'load'});
console.log('initial', await page.title(), 'error',errors,'console',logs);
await page.locator('[data-clue="tea"]').click();
await page.locator('[data-clue="clock"]').click();
await page.locator('[data-clue="letter"]').click();
await page.locator('[data-person="samer"]').click();
await page.locator('[data-topic="time"]').click();
await page.locator('#locationBar [data-location="kitchen"]').click();
await page.locator('[data-clue="vial"]').click();
await page.locator('#locationBar [data-location="hall"]').click();
await page.locator('[data-clue="camera"]').click();
await page.locator('#locationBar [data-location="garden"]').click();
await page.locator('[data-clue="print"]').click();
console.log('after clues',await page.locator('#evidenceCount').textContent(),'accuse disabled?',await page.locator('#accuseBtn').isDisabled());
await page.locator('#accuseBtn').click();
await page.locator('[data-choice="samer"]').click();
